/**
 * Get a location by its URL slug
 * @param {string} slug - URL slug (e.g., "jamshedpur", "dubai")
 * @returns {object|null} Location data object or null if not found
 */
export function getLocationBySlug(slug) {
  return LOCATIONS_DATA.find((loc) => loc.slug === slug) || null;
}

/**
 * Get all locations in a specific region
 * @param {string} region - Region name (e.g., "India", "GCC", "ASEAN", "Africa", "Europe")
 * @returns {object[]} Array of location objects
 */
export function getLocationsByRegion(region) {
  return LOCATIONS_DATA.filter((loc) => loc.region === region);
}

/**
 * Get related locations (same region, excluding current)
 * @param {string} slug - Current location slug
 * @param {number} limit - Maximum number of related locations
 * @returns {object[]} Array of related location objects
 */
export function getRelatedLocations(slug, limit = 4) {
  const current = getLocationBySlug(slug);
  if (!current) return [];
  const sameRegion = LOCATIONS_DATA.filter(
    (loc) => loc.region === current.region && loc.slug !== slug
  );
  // If not enough in same region, add from other regions
  if (sameRegion.length >= limit) return sameRegion.slice(0, limit);
  const others = LOCATIONS_DATA.filter(
    (loc) => loc.region !== current.region && loc.slug !== slug
  );
  return [...sameRegion, ...others].slice(0, limit);
}

/**
 * Get all unique regions
 * @returns {string[]} Array of region names
 */
export function getAllRegions() {
  return [...new Set(LOCATIONS_DATA.map((loc) => loc.region))];
}
